import Foundation
import CryptoKit

// Filesystem-only save boundaries. Files contain generated bytes; no decoding,
// audio engine, plug-in, application, device, or user media is touched.
@main struct ProjectStoreBoundaryTests {
    struct Failure: Error, CustomStringConvertible { let description: String }
    static func check(_ condition: @autoclosure () throws -> Bool, _ message: String) throws {
        if try !condition() { throw Failure(description: message) }
    }
    static func json(_ value: Any) throws -> Data { try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys, .fragmentsAllowed]) }
    static func project(_ path: String) -> [String: Any] {
        ["version":1,"name":"Persistence boundary","bpm":120.0,"tracks":[["id":0]],"instruments":[["id":0,"samplePath":path]],"patterns":[["id":0,"length":4,"steps":[[]]]],"sequence":[0]]
    }
    static func write(_ data: Data, _ file: URL) throws {
        try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories:true)
        try data.write(to:file)
    }
    static func warning(_ store: ProjectStore) -> String? {
        // Reflection keeps this regression runnable against the unchanged
        // checkpoint before the warning API existed.
        Mirror(reflecting:store).children.first { $0.label == "lastRecoveryWarning" }?.value as? String
    }
    static func extensionless(_ root: URL) throws {
        let source=root.appendingPathComponent("raw-recording"), alternate=root.appendingPathComponent("raw-alternative"), bytes=Data([1,2,3,4])
        try write(bytes,source);try write(Data([4,3,2,1]),alternate)
        var value=project("")
        value["audioClips"]=[["id":"phrase","track":0,"startBeat":0.0,"durationBeats":4.0,"path":source.path,
          "takeSet":["version":1,"activeID":"a","takes":[["id":"a","path":source.path,"sourceOffset":0.0],["id":"b","path":alternate.path,"sourceOffset":0.0]]]]]
        value["mediaManifest"]=[["path":source.path],["path":alternate.path]]
        let store=try ProjectStore(directory:root.appendingPathComponent("support")), destination=root.appendingPathComponent("Song.supertracker")
        _=try store.save(to:destination,snapshot:value)
        let raw=try JSONSerialization.jsonObject(with:Data(contentsOf:destination)) as! [String:Any]
        let clip=(raw["audioClips"] as! [[String:Any]])[0], takes=(clip["takeSet"] as! [String:Any])["takes"] as! [[String:Any]]
        try check((clip["path"] as! String).hasPrefix("Song.media/"),"Known clip paths without filename extensions must be collected")
        try check(takes.allSatisfy { ($0["path"] as? String)?.hasPrefix("Song.media/") == true },"Every inactive take must be portable regardless of filename extension")
        try FileManager.default.removeItem(at:source);try FileManager.default.removeItem(at:alternate)
        let opened=try store.read(destination), loaded=(opened["audioClips"] as! [[String:Any]])[0]
        try check(try Data(contentsOf:URL(fileURLWithPath:loaded["path"] as! String)) == bytes,"Collected media must survive loss of its original source")
    }
    static func opaque(_ root: URL) throws {
        let source=root.appendingPathComponent("real.wav"), opaque=root.appendingPathComponent("vendor-state.wav")
        try write(Data([1,2,3]),source);try write(Data([9,8,7]),opaque)
        let state:[String:Any]=["path":opaque.path,"nested":["samplePath":"opaque-relative.wav"],"binary":"opaque untouched"]
        var value=project(source.path);value["audioPlugins"]=[["id":"vendor","state":state]]
        value["extensions"]=["future":["path":opaque.path,"samplePath":"unknown.wav"]]
        value["mediaRelinkHistory"]=[["path":opaque.path,"samplePath":"historical.wav"]]
        var instruments=value["instruments"] as! [[String:Any]];instruments[0]["plugin"]=["state":state];value["instruments"]=instruments
        let store=try ProjectStore(directory:root.appendingPathComponent("support")),destination=root.appendingPathComponent("Opaque.supertracker")
        let saved=try store.save(to:destination,snapshot:value), opened=try store.read(destination)
        for candidate in [saved,opened] {
            for key in ["audioPlugins","extensions","mediaRelinkHistory"] {try check(try json(candidate[key]!) == json(value[key]!),"Save/Open must not reinterpret opaque or historical fields: \(key)")}
            try check(try json((candidate["instruments"] as! [[String:Any]])[0]["plugin"]!) == json(instruments[0]["plugin"]!),"Instrument vendor state must remain opaque")
        }
        try check(try FileManager.default.contentsOfDirectory(atPath:root.appendingPathComponent("Opaque.media").path).count == 1,"Opaque state must not become a media collection candidate")
    }
    static func recovery(_ root: URL) throws {
        let store=try ProjectStore(directory:root.appendingPathComponent("support")),destination=root.appendingPathComponent("Saved.supertracker")
        let value=project("");try store.update(value)
        try FileManager.default.createDirectory(at:store.recoveryURL,withIntermediateDirectories:true)
        let saved=try store.save(to:destination)
        try check(store.url == destination && !store.dirty,"A committed project must be acknowledged despite a recovery-copy failure")
        try check(try json(saved) == json(store.read(destination)),"The returned state must match the committed project")
        try check(warning(store)?.isEmpty == false,"Recovery-copy failure needs an explicit save warning")
        try FileManager.default.removeItem(at:store.recoveryURL)
        var newer=saved;newer["name"]="Retry";try store.update(newer)
        _=try store.save(to:destination)
        try check(warning(store) == nil,"A successful recovery retry must clear the stale warning")
        try check((try store.read(store.recoveryURL))["name"] as? String == "Retry","Successful retry must persist current recovery state")
    }
    static func unreadableRecovery(_ root: URL) throws {
        let support=root.appendingPathComponent("unreadable-support"), store=try ProjectStore(directory:support)
        let bytes=Data("{\"version\":1,\"name\":\"Newer build\",\"tracks\":[]}".utf8)
        try write(bytes,store.recoveryURL)
        var failed=false;do {_=try store.startupProject()}catch{failed=true}
        try check(failed,"An unreadable recovery file must be reported")
        try store.update(project(""));try store.autosave()
        let kept=try FileManager.default.contentsOfDirectory(atPath:support.path).filter { $0.hasPrefix("Recovery (unreadable") }
        try check(kept.count == 1 && (try Data(contentsOf:support.appendingPathComponent(kept[0]))) == bytes,"The blank session's autosave must not destroy the unreadable recovered session")
    }
    static func primaryFailure(_ root: URL) throws {
        let store=try ProjectStore(directory:root.appendingPathComponent("support")),destination=root.appendingPathComponent("Good.supertracker")
        _=try store.save(to:destination,snapshot:project(""));var edited=store.project!;edited["name"]="Unsaved";try store.update(edited)
        let before=try json(store.project!), previous=try Data(contentsOf:destination), bad=root.appendingPathComponent("Destination.supertracker")
        try FileManager.default.createDirectory(at:bad,withIntermediateDirectories:true)
        var failed=false;do {_=try store.save(to:bad)}catch{failed=true}
        try check(failed,"Primary write failure must still throw")
        try check(store.url == destination && store.dirty && (try json(store.project!)) == before,"Failed primary write must preserve dirty state and document identity")
        try check(try Data(contentsOf:destination) == previous,"Failed Save As must not overwrite the prior document")
    }
    static func collisionAndMissing(_ root: URL) throws {
        let source=root.appendingPathComponent("source.wav"),bytes=Data([1,2,3]),badBytes=Data([9,8,7]),destination=root.appendingPathComponent("Collision.supertracker")
        try write(bytes,source)
        let hash=SHA256.hash(data:bytes).map{String(format:"%02x",$0)}.joined(),target=root.appendingPathComponent("Collision.media/\(hash.prefix(16))-source.wav")
        try write(badBytes,target)
        let store=try ProjectStore(directory:root.appendingPathComponent("support"));let value=project(source.path);try store.update(value)
        var failed=false;do{_=try store.save(to:destination)}catch{failed=true}
        try check(failed && store.url == nil && store.dirty,"A collected-media collision must not commit")
        try check(try Data(contentsOf:target) == badBytes && Data(contentsOf:source) == bytes,"Collision must preserve both original files")
        let missing=root.appendingPathComponent("missing.wav").path
        let saved=try store.save(to:root.appendingPathComponent("Missing.supertracker"),snapshot:project(missing))
        try check((saved["instruments"] as! [[String:Any]])[0]["samplePath"] as? String == missing,"Missing sources must keep their exact repairable reference")
    }
    static func main() throws {
        let root=FileManager.default.temporaryDirectory.appendingPathComponent("ST-Persistence-boundaries-\(UUID().uuidString)")
        try FileManager.default.createDirectory(at:root,withIntermediateDirectories:true);defer{try? FileManager.default.removeItem(at:root)}
        let tests:[(String,(URL)throws->Void)]=[("extensionless clip and alternatives",extensionless),("opaque state and history",opaque),("secondary recovery failure and retry",recovery),("primary write failure remains atomic",primaryFailure),("unreadable recovery is kept",unreadableRecovery),("collected collision and missing media",collisionAndMissing)]
        var failures=0
        for (index,test) in tests.enumerated(){let folder=root.appendingPathComponent(String(index));try FileManager.default.createDirectory(at:folder,withIntermediateDirectories:true);do{try test.1(folder);print("PASS \(test.0)")}catch{failures+=1;print("FAIL \(test.0): \(error)")}}
        print("ProjectStore boundaries: \(tests.count-failures)/\(tests.count) groups passed")
        if failures>0 {exit(1)}
    }
}
